/**
 * Short, plain-language advice for the Overview tab, written from the measured
 * results. Every line is a rule over data the judge returned; nothing here is
 * generated by a model.
 *
 * Each item is { tone: "good" | "warn", text }.
 */

const MAX_ITEMS = 6;

const FLUENCY_ADVICE = {
  wpm: {
    Slow: "Speak a little faster. Aim for 110 to 150 words per minute.",
    Fast: "Slow down slightly. Aim for 110 to 150 words per minute.",
  },
  start: "Begin speaking sooner after the recording starts.",
  trailing: "Finish the sentence cleanly without a long pause at the end.",
  pauses: "Try to say it in one flow with fewer pauses.",
  longest: "Avoid long pauses in the middle of a sentence.",
  fillers: "Avoid filler sounds such as \"um\" and \"uh\".",
  pitch: "Add a little more variation in your pitch to sound natural.",
  noise: "Record in a quieter place to reduce background noise.",
};

function transcriptionAdvice(transcription) {
  if (!transcription?.rows) return [];
  const { rows, counts } = transcription;
  const items = [];

  if (counts.substitutions + counts.missing + counts.extra === 0) {
    items.push({ tone: "good", text: "Every word was read as written." });
    return items;
  }

  rows
    .filter((row) => row.status === "substitution")
    .slice(0, 2)
    .forEach((row) =>
      items.push({ tone: "warn", text: `Say "${row.expected}" clearly. It sounded like "${row.heard}".` })
    );

  const skipped = rows.filter((row) => row.status === "missing").map((row) => row.expected);
  if (skipped.length) {
    items.push({ tone: "warn", text: `Words that were skipped: ${skipped.slice(0, 4).join(", ")}.` });
  }
  const added = rows.filter((row) => row.status === "extra").map((row) => row.heard);
  if (added.length) {
    items.push({ tone: "warn", text: `Extra words were added: ${added.slice(0, 4).join(", ")}.` });
  }
  return items;
}

function pronunciationAdvice(pronunciation) {
  if (!pronunciation) return [];
  const weak = [...pronunciation.words].filter((w) => w.level !== "good").sort((a, b) => a.accuracy - b.accuracy);
  if (weak.length === 0) return [{ tone: "good", text: "All sounds matched the expected pronunciation." }];
  return weak
    .slice(0, 2)
    .map((w) => ({ tone: "warn", text: `Practise "${w.word}". Its sounds matched ${w.accuracy}%.` }));
}

function fluencyAdvice(fluency) {
  if (!fluency) return [];
  const problems = fluency.tiles.filter((t) => t.tone === "warn");
  if (problems.length === 0) return [{ tone: "good", text: "Pace and pauses were in the ideal range." }];

  return problems.slice(0, 3).map((t) => {
    const advice = t.key === "wpm" ? FLUENCY_ADVICE.wpm[t.badge] : FLUENCY_ADVICE[t.key];
    return { tone: "warn", text: advice || t.note };
  });
}

function languageAdvice(language) {
  if (!language) return [];
  const sorted = [...language.dimensions].sort((a, b) => a.score - b.score);
  const items = [];
  const weakest = sorted[0];
  if (weakest && weakest.score < 70 && weakest.justification) {
    items.push({ tone: "warn", text: `${weakest.label}: ${weakest.justification}` });
  }
  const strongest = sorted[sorted.length - 1];
  if (strongest && strongest.score >= 80 && strongest.justification) {
    items.push({ tone: "good", text: `${strongest.label}: ${strongest.justification}` });
  }
  return items;
}

function buildFeedback({ transcription, pronunciation, fluency, language }) {
  const all = [
    ...transcriptionAdvice(transcription),
    ...pronunciationAdvice(pronunciation),
    ...languageAdvice(language),
    ...fluencyAdvice(fluency),
  ];
  // Good news first, then what to work on.
  return [...all.filter((i) => i.tone === "good"), ...all.filter((i) => i.tone === "warn")].slice(0, MAX_ITEMS);
}

module.exports = { buildFeedback };
